R=[
dict(t="Biscuits au gingembre",d="Essayez notre délicieuse recette de biscuits au gingembre épicés, parfaite pour tous ceux qui aiment une gourmandise chaleureuse et savoureuse. Cette recette facile donne 18 biscuits.",p="18",s="1 biscuit (43 g)",
i=["100 g de beurre doux non salé, à température ambiante","175 g de cassonade molle","120 ml de sirop doré (golden syrup)","350 g de farine ordinaire","15 g de gingembre moulu","5 g de bicarbonate de soude"],
st=["Préchauffez le four à 180 °C/160 °C chaleur tournante/350 °F/thermostat 4.","Dans un grand bol, travaillez ensemble le beurre et le sucre en crème.","Ajoutez le sirop doré et les ingrédients secs et battez pour bien mélanger.","Une fois que tout est bien mélangé, avec vos mains (assurez-vous qu'elles sont propres !), façonnez le mélange en petites boules de taille égale.","Placez-les à 3 cm d'intervalle sur une plaque de cuisson graissée et pressez légèrement avec une fourchette.","Faites cuire au four 15 minutes, jusqu'à ce qu'ils soient dorés."]),
dict(t="Hünkar beğendi",d="Préparez cette recette de hünkar beğendi adaptée aux reins, avec de la dinde tendre en sauce tomate servie sur une purée crémeuse d'aubergines rôties, pour un délicieux repas.",p="2",s="504 g",
i=["200 g d'aubergine, en morceaux","20 g d'huile d'olive","10 g de farine blanche","125 ml de Renastep™","1 g de poivre noir","1 g de noix de muscade","30 g d'huile végétale","200 g de blanc de dinde, en petits morceaux","50 g d'oignon, finement émincé","20 g de poivron vert, finement émincé","50 g de poivron rouge, finement émincé","50 g de tomate, râpée","250 ml d'eau"],
st=["Placez les aubergines sous un gril chaud et laissez-les noircir sur toutes les faces, retirez-les du gril et laissez refroidir.","Une fois refroidies, retirez la peau noircie des aubergines et réservez.","Faites chauffer l'huile et la farine dans une casserole et remuez pour former une pâte.","Ajoutez les aubergines rôties dans la casserole et, une fois chaudes, écrasez-les pour former une purée lisse.","Réduisez le feu et ajoutez progressivement le Renastep, le poivre noir et la noix de muscade au mélange et remuez bien jusqu'à ce que le tout soit incorporé.","Laissez cuire encore 2 minutes, puis réservez.","Dans une autre poêle, faites chauffer de l'huile et ajoutez les morceaux de dinde. Laissez cuire jusqu'à ce qu'ils soient dorés.","Ajoutez les oignons et les poivrons à la viande et faites cuire jusqu'à ce qu'ils soient tendres.","Ajoutez le mélange de tomate râpée et l'eau supplémentaire, et laissez cuire jusqu'à ce que la sauce ait réduit et que la viande soit bien cuite.","Servez sur la purée d'aubergines rôties."],
h=[CHK]),
dict(t="Soupe de poivrons rouges rôtis",d="Découvrez comment préparer cette soupe fumée de poivrons rouges rôtis, mixée avec des herbes et de la crème - riche, colorée et réconfortante à chaque cuillérée chaude.",p="3",s="280 ml",
i=["200 g de poivron rouge, haché","75 g d'oignons, hachés","100 g de patates douces, hachées","10 g d'ail, haché","1 c. à soupe d'huile d'olive","2 c. à café de paprika","1 c. à café de flocons de piment","1 c. à café de poivre noir","200 ml d'eau bouillante","1 cube de bouillon à faible teneur en sel","125 ml de Renastep™"],
st=["Préchauffez le four à 200 °C.","Placez le poivron rouge, les oignons et les patates douces dans un plat de cuisson avec l'ail.","Arrosez d'huile d'olive, puis ajoutez le paprika, les flocons de piment et le poivre noir, et mélangez soigneusement jusqu'à ce que les légumes soient uniformément enrobés.","Faites rôtir au four 35 minutes, jusqu'à ce qu'ils soient tendres.","Une fois cuits, mettez-les dans une casserole avec le bouillon à faible teneur en sel et le Renastep et faites cuire à feu moyen jusqu'à ce que le tout soit chaud.","Lorsque c'est chaud, mixez jusqu'à obtenir une texture lisse, servez et savourez !"],
h=[RNFULL_T]),
dict(t="Burrito bowl",d="Cette recette de burrito bowl au tofu, au poivron, à la harissa, aux petits pois et aux oignons a été conçue pour les personnes atteintes de maladie rénale. Idéale pour un repas de week-end.",p="2",s="243 g",
i=["120 g de riz","100 g de tofu, en cubes","15 g de fécule de maïs","1 c. à café de coriandre moulue","1 c. à soupe d'huile d'olive","1 gousse d'ail, finement hachée","1 c. à café de pâte de harissa","60 g de haricots noirs, égouttés et rincés","Jus de 1 citron vert","30 g de poivron rouge, haché","20 g d'oignons, finement hachés","5 g de coriandre fraîche, finement hachée (en réserver un peu pour la garniture)","75 g de petits pois","30 g de yaourt à la noix de coco"],
st=["Faites chauffer de l'eau dans une casserole. Lorsqu'elle bout, ajoutez le riz et faites cuire 10 minutes, puis réservez","Mettez le tofu, la fécule de maïs et la coriandre moulue dans un bol. Remuez jusqu'à ce que le tofu soit bien enrobé de fécule de maïs.","Faites chauffer un peu d'huile dans une poêle et ajoutez le tofu enrobé. Faites cuire jusqu'à ce qu'il soit doré de tous les côtés, puis réservez.","Faites chauffer de l'huile dans une poêle et ajoutez l'ail, la harissa, les haricots noirs et ½ du jus de citron vert. Faites revenir jusqu'à ce que le tout soit chaud, puis réservez.","Pour le pico de gallo, mettez le poivron rouge, l'oignon et la coriandre dans un petit bol. Mélangez bien et réservez.","Dans un mixeur, mettez les petits pois, le jus de citron vert et l'huile d'olive et mixez jusqu'à ce que le tout soit incorporé tout en gardant un peu de texture","Servez le riz dans un bol et garnissez de tofu, de haricots noirs, de pico de gallo, de guacamole de petits pois et de yaourt à la noix de coco. Saupoudrez de coriandre et servez !"],
h=[CHK,RNFULL_T]),
dict(t="Risotto aux légumes",d="Essayez notre savoureuse recette de risotto aux légumes, spécialement conçue pour le régime rénal. Savourez un repas délicieux et nourrissant qui répond à vos besoins alimentaires médicaux. Cuisinez-le dès aujourd'hui !",p="4",
i=["160 g de petits pois surgelés","2 c. à soupe de persil frais","Une pincée de poivre moulu","4 c. à soupe d'huile d'olive","75 g de parmesan, finement râpé","1 cube de bouillon de légumes à teneur réduite en sel","1 petit oignon, coupé en dés","1 gousse d'ail, écrasée","100 g de brocoli","100 g de courgette","350 g de riz arborio ou de riz à risotto"],
st=["Si vous utilisez des petits pois : mettez-les dans une casserole d'eau et faites-les bouillir 5 minutes, puis égouttez. Si vous utilisez du brocoli : retirez le gros tronc et jetez-le. Coupez uniformément les bouquets et faites-les bouillir dans une casserole d'eau 5 minutes, puis égouttez. Si vous utilisez de la courgette : coupez les extrémités de la courgette et jetez-les. Coupez la courgette en rondelles, faites-la bouillir dans une casserole d'eau 5 minutes et égouttez.","Faites chauffer l'huile dans une grande casserole et ajoutez l'oignon et l'ail, faites cuire à feu moyen 5 minutes, jusqu'à ce que l'oignon soit tendre.","Retirez la casserole du feu et ajoutez le riz, en remuant jusqu'à ce que le riz soit enrobé d'huile.","Dans une carafe, ajoutez 850 ml d'eau bouillante au cube de bouillon et remuez jusqu'à ce qu'il soit dissous.","À l'aide d'une louche, ajoutez une louche de bouillon au mélange de riz et remettez sur le feu. Remuez doucement le riz jusqu'à ce que presque tout le liquide ait été absorbé. Chaque fois que le bouillon est absorbé, ajoutez une autre louche.","Environ 15 minutes après avoir ajouté le premier bouillon, incorporez les légumes précuits. Continuez à ajouter des louches de bouillon en les remuant, jusqu'à ce que le riz soit crémeux et juste tendre.","Retirez la casserole du feu et couvrez-la d'un couvercle. Laissez reposer 3 minutes, puis incorporez le persil, le parmesan et 2 pincées de poivre."]),
dict(t="Muffins au fromage",d="Ces délicieux muffins salés sont un excellent moyen d'intégrer Renastep à votre déjeuner. Préparés avec seulement quelques ingrédients, ils se préparent en 10 minutes.",p="6",s="105 g",
i=["50 ml d'huile d'olive","2 bouteilles de Renastep™","1 gros œuf","200 g de farine ordinaire","75 g de cheddar, râpé"],
st=["Préchauffez le four à 180 °C/356 °F/thermostat 4","Mélangez l'huile d'olive et le Renastep dans une carafe et réservez.","Fouettez bien l'œuf jusqu'à ce qu'il soit pâle et mousseux.","Mettez la farine dans un bol et incorporez le mélange d'huile d'olive et de Renastep ; une fois bien mélangé, incorporez délicatement le mélange d'œuf.","Incorporez le cheddar râpé et réservez.","Répartissez à parts égales dans 6 caissettes à muffins et faites cuire 25 minutes, jusqu'à ce qu'ils soient dorés et bien cuits.","Laissez refroidir, servez et savourez !"],
h=[CHK,"Renastep est un aliment destiné à des fins médicales spéciales et doit être utilisé sous surveillance médicale. Renastep est une préparation prête à l'emploi pour la prise en charge diététique de la maladie rénale à partir de 3 ans. Renastep contient du lait (protéines de lait) et du poisson (huile de thon). "+NUT]),
dict(t="Base et garniture de pizza en forme de sapin de Noël",d="Entrez dans l'esprit des fêtes avec cette pizza sapin de Noël adaptée au régime rénal, préparée avec Renastep. Essayez cette recette pour voir à quel point la vôtre peut être colorée !",p="1 sapin",
i=["125 ml de Renastep™ (1 bouteille)","2 g de levure","150 g de farine (plus un peu pour fariner)","20 g de sucre semoule","1 c. à café d'huile végétale","10 g de basilic frais","5 ml d'huile","1/2 gousse d'ail","1 c. à café (5 g) de poivron rouge, finement émincé","1 c. à café (5 g) de poivron vert, finement émincé","3 g d'oignon rouge, émincé","10 g de Violife façon mozzarella, râpé","5 g de carotte"],
st=["Préchauffez le four à 200 °C/180 °C chaleur tournante/thermostat 6.","Mettez le Renastep et la levure dans un saladier et remuez jusqu'à ce que le tout soit incorporé.","Ajoutez la farine, le sucre et l'huile au mélange de Renastep et de levure et mélangez à la main jusqu'à ce qu'une pâte se forme. Pétrissez pendant 2 minutes","Laissez lever la pâte pendant 60 minutes dans un endroit chaud.","Farinez légèrement un plan de travail propre et étalez la boule de pâte en un rectangle de 22 cm de long et 13 cm de large. À l'aide d'un couteau, coupez une ligne en diagonale depuis le centre du haut du rectangle jusqu'aux coins inférieurs gauche et droit pour former un triangle.","Placez le triangle sur une plaque de cuisson recouverte de papier sulfurisé. Utilisez le reste de la pâte pour faire un petit tronc d'arbre au bas du triangle - collez-le au sapin avec une goutte d'huile.","Pour faire le pesto, mixez ensemble le basilic, l'huile et l'ail dans un bol, à l'aide d'un mixeur plongeant.","Prenez votre base de pizza et recouvrez le sapin de pesto en l'étalant avec le dos d'une cuillère. Laissez une bordure sur le pourtour.","Disposez les poivrons émincés et l'oignon rouge sur le sapin en rangées pour imiter des guirlandes.","Saupoudrez la pizza de Violife façon mozzarella","Pour faire une étoile, coupez une grosse carotte dans le sens de la longueur pour obtenir une tranche fine, découpez une forme d'étoile et placez-la au sommet du sapin.","Faites cuire la base et la garniture au four à 200 °C/180 °C chaleur tournante/thermostat 6 pendant environ 15 minutes. Servez chaud."],
h=[RN1,RN2,"Cette recette a été spécialement conçue pour la prise en charge diététique de la maladie rénale et a été analysée à l'aide du logiciel d'analyse diététique Nutrimen."]),
dict(t="Frites de polenta",d="Cet en-cas frit facile à préparer a été créé pour que les patients rénaux puissent profiter d'une alternative aux frites pauvre en potassium. Cuisinez avec le chef Neil.",p="4",
i=["50 g de polenta","200 ml de bouillon de poulet ou de légumes à teneur réduite en sel, ou d'eau","1 c. à soupe de parmesan (facultatif)","2 c. à soupe d'huile de tournesol"],
st=["Portez le bouillon à ébullition dans une casserole et ajoutez la polenta en filet continu. Faites cuire en remuant continuellement pendant 5 minutes (attention, la polenta bouillonne fortement).","Retirez du feu et incorporez le parmesan (le cas échéant).","Versez le mélange à la cuillère sur la plaque et aplatissez-le en une grande forme rectangulaire d'environ 5 à 10 mm d'épaisseur (selon l'épaisseur souhaitée pour vos frites !) avec le dos de la cuillère en bois. Laissez refroidir 10 à 15 minutes.","Placez les frites sur une plaque de cuisson et badigeonnez-les d'huile. Faites cuire au four à température moyenne (180 ºC) pendant 15 minutes, jusqu'à ce qu'elles soient dorées. Vous pouvez aussi les faire frire dans un fond d'huile, légèrement et uniformément sur les 4 faces. Servez chaud et savourez ! Cette recette est tirée du Kidney Friendly Cookbook, réalisé par des diététiciens et des assistants en diététique d'une unité de néphrologie pédiatrique au Royaume-Uni. Veuillez vérifier auprès de votre diététicien(ne) ou de votre médecin que cette recette vous convient."]),
dict(t="Bialys",d="Découvrez comment préparer ces bialys moelleux et fondants adaptés aux reins, pauvres en sodium et à teneur équilibrée en protéines - un en-cas salé parfait et plein de saveur.",p="8",s="117 g",
i=["500 g de farine de blé forte pour pain","1 c. à café d'ail en poudre","7 g de levure instantanée","300 ml d'eau tiède","1 c. à soupe d'huile d'olive","100 g d'oignons, finement hachés","2 gousses d'ail, hachées","1 c. à café de poivre noir","2 c. à café de graines de pavot"],
st=["Mélangez la farine, l'ail en poudre et la levure dans un bol.","Faites un puits, versez-y l'eau tiède et remuez pour former une pâte.","Pétrissez la pâte pendant 5 minutes, jusqu'à ce qu'elle soit lisse, puis placez-la dans un bol légèrement huilé, couvrez et laissez lever pendant 1 heure.","Pendant ce temps, faites chauffer l'huile dans une poêle et ajoutez les oignons, l'ail et le poivre noir et faites-les ramollir 5 minutes.","Incorporez les graines de pavot, retirez la poêle du feu et réservez.","Une fois la pâte levée, divisez-la en 8 portions égales et façonnez-les en boules.","Appuyez au centre de chaque boule pour créer un creux. Prenez-la et faites-la tourner lentement entre vos mains afin que la pâte au centre devienne plus fine, en veillant à ne pas déchirer le centre.","Répétez cette opération pour les 8 boules.","Placez tous les bialys sur une plaque de cuisson et répartissez uniformément la garniture au centre de chacun.","Faites cuire 20 minutes, jusqu'à ce qu'ils soient dorés.","Servez et savourez !"]),
dict(t="Blancs d'œufs brouillés (3)",d="Informations nutritionnelles pour des blancs d'œufs brouillés",p="1",s="3 blancs d'œufs brouillés",
i=["3 œufs entiers"],
st=["Cassez 3 œufs et séparez les blancs dans un petit bol.","Fouettez les blancs d'œufs jusqu'à ce qu'ils soient légèrement mousseux.","Faites chauffer une poêle antiadhésive à feu moyen et enduisez-la légèrement d'huile en spray.","Versez les blancs d'œufs dans la poêle.","Laissez-les cuire quelques secondes, puis remuez délicatement avec une spatule.","Continuez à cuire et à remuer jusqu'à ce que les blancs d'œufs soient fermes et qu'il ne reste plus de liquide.","Retirez du feu et servez chaud."]),
dict(t="Épinards sautés",d="Il n'a jamais été aussi simple d'ajouter des légumes verts non féculents à votre assiette qu'avec ces épinards sautés tout simples. Prêts en quelques minutes, c'est une excellente option adaptée aux personnes diabétiques pour les repas de la semaine.",p="4",s="1 tasse",
i=["2 c. à soupe d'huile d'olive","2 gousses d'ail (émincées)","1 livre d'épinards surgelés (lavés et tiges retirées)","1/4 c. à café de sel","1/4 c. à café de poivre noir"],
st=["Dans une grande poêle, faites chauffer l'huile d'olive à feu moyen.","Ajoutez l'ail dans la poêle et faites-le revenir 1 à 2 minutes, jusqu'à ce qu'il dégage son parfum.","Ajoutez les épinards frais dans la poêle par petites quantités, en laissant chaque quantité flétrir avant d'en ajouter d'autres.","Mélangez délicatement les épinards pour les enrober d'huile d'olive et d'ail.","Continuez à les faire sauter 2 à 3 minutes, jusqu'à ce que les épinards soient flétris et tendres.","Assaisonnez de sel et de poivre noir selon votre goût. Mélangez.","Servez avec des quartiers de citron à côté, si désiré."]),
dict(t="Assiette à tremper à la grecque",d="C'est un en-cas léger et rafraîchissant qui équilibre parfaitement les céréales complètes avec des saveurs fraîches et salées.",p="1",s="1/2 pita de blé complet (environ 2 onces), 2 c. à soupe de sauce tzatziki, 1 tasse de tomates cerises",
i=["2 onces de pita de blé complet","2 c. à soupe de sauce tzatziki allégée en matières grasses","1 tasse de tomates cerises"],
st=["Pour un meilleur goût, faites légèrement griller votre pita de blé complet au grille-pain ou au four jusqu'à ce qu'il soit chaud et légèrement souple.","Coupez le pita en triangles (quartiers) et placez-les sur une assiette à côté d'un petit bol de tzatziki et des tomates cerises entières pour tremper.","Savourez immédiatement pendant que le pita est chaud."]),
dict(t="Salade niçoise au tofu",d="Cette version fraîche de la salade niçoise végétarienne et pauvre en matières grasses utilise du tofu saisi à la place du thon pour apporter des protéines végétales, avec des ingrédients classiques comme des haricots verts croquants, des pommes de terre tendres et des œufs durs. À la place de la vinaigrette habituelle, une sauce française crémeuse sans matières grasses apporte une touche acidulée sans graisses saturées supplémentaires. C'est un repas adapté aux personnes diabétiques, riche en fibres, en couleurs et en croquant.",p="4",s="4 tasses de légumes, 3 onces de tofu",
i=["1 livre de petites pommes de terre rouges (coupées en deux)","2 gros œufs","12 onces de haricots verts frais (équeutés)","6 tasses de laitue beurre (hachée)","1 tasse de tomates cerises (coupées en deux)","1/2 tasse de concombre (finement tranché)","1/2 once d'olives Kalamata (coupées en deux)","1/2 tasse de sauce pour salade de style français crémeuse sans matières grasses","12 onces de tofu extra ferme (pressé et coupé en lanières de 1/2 pouce)","2 c. à café de sauce soja à teneur réduite en sodium","1 c. à café de moutarde de Dijon","1/2 c. à café d'ail en poudre","1 pincée de poivre noir"],
st=["Préparez les pommes de terre, les œufs et les haricots verts : placez les pommes de terre coupées en deux dans une casserole d'eau froide. Portez à ébullition et faites cuire 10 à 12 minutes, jusqu'à ce qu'elles soient tendres. Pendant les 8 dernières minutes de cuisson, plongez délicatement les œufs. Pendant les 2 dernières minutes, ajoutez les haricots verts. Égouttez le tout, transférez les haricots verts dans un bain d'eau glacée et refroidissez les œufs à l'eau froide. Écalez les œufs une fois refroidis et coupez-les en quartiers.","Préparez et faites cuire le tofu : dans un plat peu profond, fouettez ensemble la sauce soja, la moutarde de Dijon, l'huile d'olive, l'ail en poudre et le poivre noir. Ajoutez les tranches de tofu et laissez mariner 5 à 10 minutes. Faites chauffer une poêle antiadhésive à feu moyen-vif. Saisissez le tofu 3 à 4 minutes de chaque côté, jusqu'à ce qu'il soit doré et légèrement croustillant. Réservez.","Dressez la salade : sur un grand plat ou des assiettes individuelles, disposez la laitue, les pommes de terre, les haricots verts, les tomates, les concombres, les olives et les œufs. Ajoutez des tranches de tofu saisi par-dessus. Arrosez de sauce juste avant de servir."]),
dict(t="Salade Cobb au poulet",d="Cette salade Cobb classique au poulet est une option adaptée aux personnes diabétiques pour un repas copieux. Riche en protéines et en saveur, elle est assez rassasiante pour vous caler pendant des heures.",p="6",s="1-1/3 tasse",
i=["1 c. à soupe d'huile d'olive","1 c. à café d'origan séché","1 c. à café d'ail en poudre","1/4 c. à café de poivre noir","1 livre de blancs de poulet sans os et sans peau","8 tasses de jeunes pousses de salade","1 tasse de tomates cerises (coupées en deux)","1 tasse de concombre (en dés)","1/2 tasse d'oignon rouge (finement haché)","1 avocat moyen (en dés)","1/4 tasse d'olives Kalamata (dénoyautées et tranchées)","2 gros œufs durs (tranchés)","1/2 tasse de vinaigrette balsamique allégée"],
st=["Préchauffez un gril ou une poêle-gril à feu moyen-vif.","Dans un bol, mélangez l'huile d'olive, l'origan séché, l'ail en poudre, le sel et le poivre noir.","Badigeonnez les blancs de poulet du mélange d'huile d'olive.","Faites griller le poulet environ 6 à 8 minutes de chaque côté, jusqu'à ce qu'il soit bien cuit à une température interne de 165 degrés F.","Laissez reposer le poulet quelques minutes avant de le couper en lanières.","Dans un grand bol, disposez les jeunes pousses de salade, les tomates cerises coupées en deux, le concombre en dés, l'oignon rouge finement tranché, l'avocat en dés et les olives Kalamata tranchées.","Disposez le poulet grillé tranché sur la salade.","Ajoutez les œufs durs tranchés.","Arrosez la salade de vinaigrette balsamique."]),
dict(t="Nouvelles fourmis sur un tronc",d="Une gourmandise classique que les enfants adorent, avec une touche originale ! Les cerises séchées apportent de la douceur, et les graisses saines et les protéines du beurre d'amande en font un goûter parfait et équilibré.",p="1",s="2 branches de céleri garnies",
i=["2 branches de céleri (parées et lavées)","1 1/2 c. à soupe de beurre d'amande","2 c. à café de cerises séchées non sucrées"],
st=["Remplissez chaque branche de céleri de purée d'oléagineux et garnissez de fruits secs. Servez immédiatement."]),
]
